<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { useSupplierStore } from '@/stores/supplier'
import { propertySettlementsApi as api, type SettlementCard, type SettlementDetail, type SettlementCapabilities } from '@/api/propertySettlements'
import ActionBar, { type ActionItem } from '@/components/ui/ActionBar.vue'
import DateInput from '@/components/ui/DateInput.vue'
import PropertyButton from '@/components/property/PropertyButton.vue'
import SettlementDocumentEditor from '@/components/property/settlements/SettlementDocumentEditor.vue'
import SettlementDispositionEditor from '@/components/property/settlements/SettlementDispositionEditor.vue'
import SettlementDossierPanel from '@/components/property/settlements/SettlementDossierPanel.vue'
import SettlementPlanView from '@/components/property/settlements/SettlementPlanView.vue'
import SettlementDeadlinesPanel from '@/components/property/settlements/SettlementDeadlinesPanel.vue'
import { propertyError } from '@/components/property/propertyError'
import { formatDate, formatDateTime } from '@/composables/useFormat'
import { settlementMoney as money, settlementInput as input, settlementBox as box } from '@/components/property/settlements/settlementForm'
const { t } = useI18n(), route = useRoute(), router = useRouter()
const supplier = computed(() => useSupplierStore().currentSupplierId), items = ref<SettlementCard[]>([]), next = ref<number | null>(null), detail = ref<SettlementDetail | null>(null)
const capabilities = ref<SettlementCapabilities>({ manage: false, post: false, reverse: false }), busy = ref(false), error = ref(''), notice = ref(''), editing = ref(false), revision = ref<SettlementDetail | null>(null)
const stale = ref(false)
const reversing = ref(false), reverseDate = ref(''), reverseReason = ref(''), reverseAck = ref(false), reverseForm = ref<HTMLFormElement | null>(null)
let epoch = 0, reverseToken = crypto.randomUUID()
const active = computed(() => detail.value?.applications.find(a => a.active) ?? null)
const hasHistory = computed(() => !!detail.value?.applications.length)
const selectedId = computed(() => Number(route.params.id) || null)
onBeforeUnmount(() => epoch++)
watch([supplier, selectedId], () => { epoch++; items.value = []; detail.value = null; editing.value = false; revision.value = null; reversing.value = false; error.value = ''; notice.value = ''; busy.value = false; capabilities.value = { manage: false, post: false, reverse: false }; void load() }, { immediate: true })
async function load(more = false) {
 if (!supplier.value || busy.value) return
 const id = supplier.value, ticket = epoch; busy.value = true; error.value = ''
 try {
  const page = await api.list(id, more ? next.value ?? 0 : 0)
  if (ticket !== epoch || supplier.value !== id) return
  items.value = more ? [...items.value, ...page.items] : page.items; next.value = page.next_cursor; capabilities.value = page.capabilities
  if (selectedId.value) { const result = await api.detail(id, selectedId.value); if (ticket === epoch && supplier.value === id) { detail.value = result; capabilities.value = result.capabilities; stale.value = false } }
 } catch (e) { if (ticket === epoch) error.value = propertyError(e, t) } finally { if (ticket === epoch && supplier.value === id) busy.value = false }
}
function create() { editing.value = true; revision.value = null; reversing.value = false }
function revise() { if (!detail.value || active.value || !capabilities.value.manage) return; revision.value = detail.value; editing.value = true; reversing.value = false }
async function saved(id: number) { editing.value = false; revision.value = null; notice.value = t('propertySettlements.saved'); if (selectedId.value === id) await load(); else await router.push({ name: 'property-service-settlements', params: { id } }) }
function beginReverse() { if (!detail.value || !active.value || !capabilities.value.reverse) return; reversing.value = true; reverseDate.value = active.value.accounting_date; reverseReason.value = ''; reverseAck.value = false; reverseToken = crypto.randomUUID() }
async function reverse() {
 if (busy.value || !supplier.value || !detail.value || !active.value || !capabilities.value.reverse || !reverseAck.value || !reverseForm.value?.reportValidity()) return
 const id = supplier.value, ticket = epoch, application = active.value.id, version = detail.value.current_summary.row_version; busy.value = true; error.value = ''
 try { await api.reverse(id, application, { accounting_date: reverseDate.value, expected_version: version, reason: reverseReason.value, idempotency_key: reverseToken }); if (ticket === epoch && id === supplier.value) { reversing.value = false; busy.value = false; await load(); notice.value = t('propertySettlements.reversed') } }
 catch (e) { if (ticket === epoch) { reversing.value = false; stale.value = true; error.value = propertyError(e, t) + ' ' + t('propertySettlements.refreshConflict') } } finally { if (ticket === epoch && id === supplier.value) busy.value = false }
}
const actions = computed<ActionItem[]>(() => [{ key: 'new-settlement', label: t('propertySettlements.newDocument'), icon: 'plus', variant: 'primary', tier: 'primary', disabled: busy.value || !capabilities.value.manage, run: create }, { key: 'refresh-settlements', label: t('propertySettlements.refresh'), icon: 'cycle', tier: 'secondary', disabled: busy.value, run: () => { void load() } }])
const detailActions = computed<ActionItem[]>(() => active.value ? [{ key: 'review-reversal', label: t('propertySettlements.reviewReversal'), icon: 'trash', variant: 'danger', tier: 'secondary', disabled: busy.value || stale.value || !capabilities.value.reverse, run: beginReverse }] : [{ key: 'new-revision', label: t('propertySettlements.newRevision'), icon: 'edit', variant: 'warning', tier: 'secondary', disabled: busy.value || stale.value || !capabilities.value.manage, run: revise }])
const reversalActions = computed<ActionItem[]>(() => [{ key: 'reverse-settlement', label: t('propertySettlements.reverse'), icon: 'trash', variant: 'danger', tier: 'primary', disabled: busy.value || !reverseAck.value || !capabilities.value.reverse, run: () => { void reverse() } }, { key: 'cancel-reversal', label: t('propertySettlements.cancel'), icon: 'x', tier: 'secondary', disabled: busy.value, run: () => { reversing.value = false } }])
</script>
<template>
 <div class="space-y-5"><div><h1 class="text-2xl font-semibold">{{ t('propertySettlements.title') }}</h1><p class="text-sm text-neutral-500 mt-0.5">{{ t('propertySettlements.help') }}</p></div><p v-if="error" role="alert" class="rounded border border-danger-300 bg-danger-50 p-3 text-danger-700">{{ error }}</p><p v-if="notice" role="status" class="rounded border p-3">{{ notice }}</p><ActionBar :actions="actions" />
 <SettlementDocumentEditor v-if="editing && supplier" :key="`${supplier}:${revision?.id || 'new'}`" :supplier="supplier" :capabilities="capabilities" :revision="revision" @saved="saved" @cancel="editing = false" />
 <section class="space-y-3"><h2 class="font-semibold">{{ t('propertySettlements.documents') }}</h2><p v-if="!items.length && !busy" class="text-sm text-neutral-500">{{ t('propertySettlements.empty') }}</p><article v-for="v in items" :key="v.id" class="flex flex-wrap items-center gap-3 rounded-lg border bg-surface p-3"><div class="min-w-0 flex-1"><p class="font-medium">{{ v.unit.label }} · {{ v.service.label }}</p><p class="text-sm">{{ t('propertySettlements.periodLabel', { from: formatDate(v.period_from), to: formatDate(v.period_to) }) }} · {{ t('propertySettlements.revision', { number: v.revision_no }) }} · {{ t(v.current_summary.active ? 'propertySettlements.statusApplied' : 'propertySettlements.statusDocument') }}</p><p class="text-sm">{{ t('propertySettlements.prescribed_cents') }} {{ money(v.prescribed_cents) }} · {{ t('propertySettlements.paid_cents') }} {{ money(v.paid_at_cutoff_cents) }} · {{ t('propertySettlements.actual_cents') }} {{ money(v.actual_cents) }}</p></div><PropertyButton icon="eye" :disabled="busy" @click="router.push({ name: 'property-service-settlements', params: { id: v.id } })">{{ t('propertySettlements.detail') }}</PropertyButton></article><PropertyButton v-if="next !== null" icon="plus" :disabled="busy" @click="load(true)">{{ t('propertySettlements.more') }}</PropertyButton></section>
 <template v-if="detail && !editing"><section :class="box" data-section="settlement-detail"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="font-semibold">{{ detail.unit.label }} · {{ detail.service.label }}</h2><p>{{ t('propertySettlements.revision', { number: detail.revision_no }) }} · {{ t('propertySettlements.periodLabel', { from: formatDate(detail.document.period_from), to: formatDate(detail.document.period_to) }) }}</p></div><ActionBar :actions="detailActions" /></div><p class="text-sm">{{ t('propertySettlements.cutoff') }}: {{ formatDateTime(detail.document.cutoff_at) }} · {{ t('propertySettlements.knownAt') }}: {{ formatDateTime(detail.document.known_at) }}</p><p class="text-sm">{{ t('propertySettlements.evidence') }}: {{ detail.document.evidence }}</p><dl class="grid gap-3 sm:grid-cols-3"><div v-for="key in ['prescribed_cents', 'paid_cents', 'actual_cents'] as const" :key="key"><dt>{{ t(`propertySettlements.${key}`) }}</dt><dd class="text-lg font-semibold">{{ money(detail.document[key]) }}</dd></div></dl><p class="text-sm text-neutral-500">{{ t('propertySettlements.immutableNotice') }}</p><dl class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="(value, key) in detail.document.amounts" :key="key"><dt class="text-sm text-neutral-500">{{ t(`propertySettlements.amounts.${key}`) }}</dt><dd>{{ money(value) }}</dd></div></dl></section>
 <SettlementDossierPanel v-if="detail.dossier && supplier" :key="`${supplier}:${detail.id}:dossier`" :supplier="supplier" :value="detail.dossier" :manage="capabilities.manage" :period-from="detail.document.period_from" :period-to="detail.document.period_to" @updated="load()" />
 <SettlementDeadlinesPanel v-if="supplier" :key="`${supplier}:${detail.id}:deadlines`" :supplier="supplier" :document-id="detail.id" :manage="capabilities.manage" />
 <section :class="box" data-section="current-summary"><h2 class="font-semibold">{{ t('propertySettlements.currentSummary') }}</h2><p class="text-sm text-neutral-500">{{ t('propertySettlements.partialCurrent') }}</p><p v-if="!detail.current_summary.active">{{ t('propertySettlements.noActiveApplication') }}</p><article v-for="(credit, i) in detail.current_summary.credits" :key="credit.id" class="rounded border p-3"><h3>{{ t('propertySettlements.creditNumber', { number: i + 1 }) }}</h3><p>{{ t('propertySettlements.creditBalance') }}: {{ money(credit.balance_cents) }} · {{ t('propertySettlements.creditReserved') }}: {{ money(credit.reserved_cents) }} · {{ t('propertySettlements.creditAvailable') }}: {{ money(credit.available_cents) }}</p></article><article v-for="(claim, i) in detail.current_summary.claims" :key="claim.id" class="rounded border p-3"><h3>{{ t('propertySettlements.claimNumber', { number: i + 1 }) }}</h3><p>{{ t('propertySettlements.principal') }}: {{ money(claim.principal_cents) }} · {{ t('propertySettlements.physicalPaid') }}: {{ money(claim.paid_cents) }}</p><p v-for="(a, index) in claim.accessories" :key="index">{{ t(`propertyPayments.component.${a.component}`) }}: {{ money(a.amount_cents) }}</p></article></section>
 <SettlementDispositionEditor v-if="!active && !hasHistory && supplier" :key="`${supplier}:${detail.id}`" :supplier="supplier" :detail="detail" @applied="load()" />
 <section v-if="reversing && active" :class="box" data-section="reverse-review"><h2 class="font-semibold">{{ t('propertySettlements.reviewReversal') }}</h2><p>{{ t('propertySettlements.reverseHelp') }}</p><SettlementPlanView :plan="active.receipt.preview.plan" /><form ref="reverseForm" class="grid gap-3 sm:grid-cols-2" @submit.prevent="reverse"><fieldset :disabled="busy" class="contents"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.accountingDate') }}<DateInput :class="input" v-model="reverseDate" required data-field="reverse-date" /></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.reverseReason') }}<input v-model="reverseReason" required :class="input" data-field="reverse-reason" /></label><label class="flex flex-wrap items-center gap-2 sm:col-span-2"><input v-model="reverseAck" type="checkbox" data-field="reverse-ack" />{{ t('propertySettlements.reverseAcknowledgement') }}</label></fieldset></form><ActionBar :actions="reversalActions" /></section>
 <section v-if="detail.applications.length" :class="box"><h2 class="font-semibold">{{ t('propertySettlements.applicationHistory') }}</h2><article v-for="a in detail.applications" :key="a.id" class="space-y-2 border-t pt-3"><h3>{{ formatDate(a.accounting_date) }} · {{ t(a.reversal_of ? 'propertySettlements.statusReversal' : a.active ? 'propertySettlements.statusApplied' : 'propertySettlements.statusReversed') }}</h3><SettlementPlanView :plan="a.receipt.preview.plan" /></article></section>
 </template></div>
</template>
